// Reserve one credit for a scan identified by the client's idempotency key.
// Returns { replay: true, request } for an already-succeeded key.
export async function reserveScan(userId, idempotencyKey) {
  return tx(async (c) => {
    const acct = await lockAccount(c, userId);
    await expireAllowanceIfDue(c, acct);
    await releaseStale(c, acct);

    const existing = (
      await c.query("select * from scan_requests where user_id = $1 and idempotency_key = $2", [userId, idempotencyKey])
    ).rows[0];
    if (existing?.status === "succeeded") return { replay: true, request: existing };
    if (existing?.status === "pending") throw new ScanInProgress("This scan is already running");

// Policy table. Each route checks its rules in order and stops at the first block.
export const policies = {
  receiptScan: () => [
    // Per client: a handful of scans in a burst, about one every 2 minutes after that.
    { name: "receipt-scan:ip", limiter: limiter("receipt-scan:ip", Ratelimit.tokenBucket(1, "2 m", 5)) },
    // Global ceiling on paid OCR calls. Caps spend even if someone rotates IPs.
    { name: "receipt-scan:global", limiter: limiter("receipt-scan:global", Ratelimit.fixedWindow(300, "1 h")), key: "all" },
  ],
  invites: () => [
    { name: "invites:ip", limiter: limiter("invites:ip", Ratelimit.slidingWindow(10, "1 h")) },
    // Per recipient: stops anyone from flooding one inbox with invites.
    { name: "invites:recipient", limiter: limiter("invites:recipient", Ratelimit.slidingWindow(3, "24 h")) },
  ],
};

/**
 * Welcome email. Call once after the user row is created.
 * user: { id, email, name? }
 */
export async function sendWelcomeEmail(user) {
  const result = await sendEmail({
    to: user.email,
    ...welcomeEmail({ name: user.name }),
    idempotencyKey: `welcome:${user.id}`,
  });
  if (!result.ok) console.error("[email] welcome failed", { userId: user.id, ...result });
  return result;
}

